    },
    {
      "id": "i2",
      "statement": "A message claiming to be from IT asks reception to confirm their password on a fake login page.",
      "accepted": [
        "Phishing / social engineering"
      ],
      "feedback": "Credential theft via a deceptive message is phishing / social engineering."
    },
    {
      "id": "i3",
      "statement": "Attackers flood Northbank’s booking website so patients cannot book appointments.",
      "accepted": [
        "Denial of service"
      ],
      "feedback": "Overwhelming a service so legitimate users cannot use it is denial of service."
    },
    {
      "id": "i4",
      "statement": "A leaving member of staff copies patient contact lists they are not allowed to take.",
      "accepted": [
        "Unauthorised access / insider"
      ],
      "feedback": "Misuse by someone with insider access is unauthorised access / insider misuse."
    },
    {
      "id": "i5",
      "statement": "A stolen clinic laptop is taken from an unlocked staff room overnight.",
      "accepted": [
        "Physical / environmental"
      ],
      "feedback": "Theft of a device from premises is a physical security incident."
    },
    {
      "id": "i6",
      "statement": "Someone pretends to be a delivery courier to walk into a restricted records area.",
      "accepted": [
        "Phishing / social engineering"
      ],
      "feedback": "In-person deception to gain entry is social engineering (not malware)."
    }
  ],
  "note": "Authored catalogue classification (D3c)."
}
