{
  "formula": "A threat exploits a vulnerability to cause a cyber security incident.",
  "definitions": {
    "threat": {
      "term": "Threat",
      "text": "A threat is a person, group or event that could deliberately or accidentally harm systems, networks or data. Threats include cyber criminals, malicious insiders, ransomware operators and social engineers."
    },
    "vulnerability": {
      "term": "Vulnerability",
      "text": "A vulnerability is a weakness in a system, process or behaviour that a threat could use. Examples include weak passwords, missing software patches, unlocked doors and staff who trust phishing emails without checking."
    },
    "incident": {
      "term": "Cyber security incident",
      "text": "An incident is the harmful outcome when a threat successfully exploits a vulnerability. It may affect confidentiality, integrity, availability or a combination of CIA aims."
    }
  },
  "workedExamples": [
    {
      "id": "ex-phishing",
      "title": "Phishing at Northbank",
      "threat": "A phisher sends a convincing fake email.",
      "vulnerability": "A staff member trusts the email and does not verify the sender.",
      "incident": "Login credentials are stolen and an attacker accesses internal systems.",
      "ciaNote": "Confidentiality is affected when unauthorised people obtain account access."
    },
    {
      "id": "ex-malware",
      "title": "Malware through unpatched software",
      "threat": "Malware designed to spread across a network.",
      "vulnerability": "A server runs software that has not been patched against a known flaw.",
      "incident": "Systems are compromised and services become unavailable.",
      "ciaNote": "Availability and integrity may both be affected depending on what the malware does."
    }
  ],
  "misconceptions": [
    {
      "myth": "A threat and a vulnerability are the same thing.",
      "reality": "A threat is the danger source; a vulnerability is the weakness that can be exploited. Both must be present for an incident to occur."
    },
    {
      "myth": "Technology alone causes incidents.",
      "reality": "People and processes matter too. Poor training, weak policies and human error are common vulnerabilities."
    },
    {
      "myth": "If you have a firewall, you have no vulnerabilities.",
      "reality": "Controls reduce risk but do not remove every weakness. Misconfigured rules, unpatched software and social engineering can still succeed."
    }
  ],
  "comparisonPoints": [
    {
      "aspect": "What it is",
      "threat": "The potential cause of harm (who or what might attack)",
      "vulnerability": "The weakness that could be exploited (what is unprotected or flawed)"
    },
    {
      "aspect": "Example at Northbank",
      "threat": "A scammer calling reception pretending to be IT support",
      "vulnerability": "Staff have not been trained to verify unexpected support calls"
    },
    {
      "aspect": "Can you remove it completely?",
      "threat": "You cannot eliminate all threats, but you can reduce exposure",
      "vulnerability": "You can fix or reduce many vulnerabilities through controls and training"
    },
    {
      "aspect": "OCR exam focus",
      "threat": "Name the actor or attack method clearly",
      "vulnerability": "Identify the specific weakness — technical, physical or human"
    }
  ]
}
